聽得我超級心動😍😍

一入口就是酸爽的檸檬味～～
膠原茶凍超級滑順咕溜
偶爾想吃點料
但又不想咀嚼就很推薦這款👍🏻👍🏻
心情美好、氣色自然也就跟著好啦🎆🎆

他們也很推薦另一款「膠原貴妃」
是由高敏敏營養師推薦
安心感🆙️🆙️
下次想換喝這款
喝手搖飲的罪惡感直接少一半🤣🤣

