            map: '',
            content: `✨️#哈利利市集

I人逛哈利利市集
甜點＆明碼標價紀念品店

似乎是中東傳統甜點「庫納法Knafeh」
裹上金黃酥脆細絲，再淋滿糖漿
螞蟻人會愛💥

看到 CAMEL BAZAR 招牌後
沿著樓梯到2樓
這裡有許多人推薦的紀念品店🛍
對不太會殺價的I人很友善

會經過一家有各式包包、衣服
也是明碼標價的小店
帆布袋比我在別家殺價完的還便宜🥹

來逛許多人推薦的 Jordi Bazar Shop
紀念品種類很多
像這組金字塔擺飾，印象中不到30埃鎊💥
Jordi 1樓也有分店
但商品種類少很多～

品質不用期待太高
就當是旅行的小紀念🤎

#花現埃及 #埃及美食 #egypt #埃及景點`
